<template>
  <div class="login-page">
    <div class="login-wrap">

      <!-- ── Левая панель ─────────────────────────────── -->
      <div class="left-panel">
        <div class="left-glow left-glow--top"></div>
        <div class="left-glow left-glow--bottom"></div>

        <!-- Логотип -->
        <div class="brand">
          <img src="@/assets/images/logo.png" alt="Kibernetiki" class="brand-logo" />
          <span class="brand-name"></span>
        </div>

        <!-- Описание -->
        <div class="left-content">
          <h2 class="left-title">Аналитика<br>для <span>бизнеса</span></h2>
          <p class="left-sub"></p>
        </div>

        <!-- Статистика -->
        <div class="stats">
          <div class="stat">
            <span class="stat-dot" style="background:#22c55e"></span>
            <span class="stat-text">Все показатели сети — в одном месте</span>
          </div>
          <div class="stat">
            <span class="stat-dot" style="background:#f97316"></span>
            <span class="stat-text">Контроль выполнения плана по каждому магазину</span>
          </div>
          <div class="stat">
            <span class="stat-dot" style="background:#6366f1"></span>
            <span class="stat-text">Обновление данных в понедельник и пятницу</span>
          </div>
        </div>
      </div>

      <!-- ── Правая панель ────────────────────────────── -->
      <div class="right-panel">
        <div class="form-header">
          <h2 class="form-title">Добро пожаловать</h2>
          <p class="form-sub">Введите данные для входа в систему</p>
        </div>

        <div class="fields">
          <!-- Логин -->
          <div class="field-wrap">
            <label class="field-label">Логин</label>
            <div class="field" :class="{ 'field--focus': focusLogin, 'field--error': loginError }">
              <span class="field-icon">
                <v-icon size="18" color="#94a3b8">mdi-account-outline</v-icon>
              </span>
              <input
                  v-model="login"
                  type="text"
                  placeholder="Введите логин"
                  autocomplete="username"
                  @focus="focusLogin = true"
                  @blur="focusLogin = false"
                  :disabled="isShowAuthLoader || isAuthSuccess"
              />
            </div>
          </div>

          <!-- Пароль -->
          <div class="field-wrap">
            <label class="field-label">Пароль</label>
            <div class="field" :class="{ 'field--focus': focusPass, 'field--error': passError }">
              <span class="field-icon">
                <v-icon size="18" color="#94a3b8">mdi-lock-outline</v-icon>
              </span>
              <input
                  v-model="password"
                  :type="showPassword ? 'text' : 'password'"
                  placeholder="Введите пароль"
                  autocomplete="current-password"
                  @focus="focusPass = true"
                  @blur="focusPass = false"
                  :disabled="isShowAuthLoader || isAuthSuccess"
              />
              <button class="show-btn" @click="togglePasswordVisibility" type="button">
                <v-icon size="18" color="#94a3b8">
                  {{ showPassword ? 'mdi-eye-off-outline' : 'mdi-eye-outline' }}
                </v-icon>
              </button>
            </div>
          </div>
        </div>

        <!-- Кнопка входа -->
        <button
            class="submit-btn"
            :class="{ 'submit-btn--loading': isShowAuthLoader, 'submit-btn--success': isAuthSuccess }"
            :disabled="!availableConfirmBtn || isShowAuthLoader || isAuthSuccess"
            @click="checkAuth"
        >
          <span v-if="isAuthSuccess" class="btn-content">
            <v-icon size="18">mdi-check</v-icon>
            Вход выполнен
          </span>
          <span v-else-if="isShowAuthLoader" class="btn-content">
            <div class="btn-spinner"></div>
            Проверка...
          </span>
          <span v-else class="btn-content">
            <v-icon size="18">mdi-login</v-icon>
            Войти в систему
          </span>
        </button>

        <div class="form-footer">Панель управления показателями сети магазинов электроники</div>
      </div>
    </div>

    <!-- Snackbar -->
    <v-snackbar v-model="snackbar" color="error" timeout="4000" location="top">
      {{ snackbarText }}
      <template v-slot:actions>
        <v-btn variant="text" @click="snackbar = false">✕</v-btn>
      </template>
    </v-snackbar>

    <!-- Dialog -->
    <v-dialog v-model="dialog" max-width="360">
      <v-card border rounded="xl">
        <v-card-title class="pa-6 pb-2" style="font-weight:700">{{ dialogTitle }}</v-card-title>
        <v-card-text class="pa-6 pt-2" style="color:#64748b">{{ dialogText }}</v-card-text>
        <v-card-actions class="pa-4 pt-0">
          <v-spacer />
          <v-btn color="error" variant="tonal" rounded="lg" @click="dialog = false">Понятно</v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>
  </div>
</template>

<script>
import $ from 'jquery'
import { ROLE_HOME } from '@/config/managers.config'

export default {
  name: 'LoginComponent',

  emits: ['updateUserStatus'],

  data() {
    return {
      login:           '',
      password:        '',
      showPassword:    false,
      focusLogin:      false,
      focusPass:       false,
      loginError:      false,
      passError:       false,
      isShowAuthLoader: false,
      isAuthSuccess:   false,
      snackbar:        false,
      snackbarText:    '',
      dialog:          false,
      dialogTitle:     '',
      dialogText:      '',
    }
  },

  computed: {
    availableConfirmBtn() {
      return this.validateLogin(this.login) && this.validatePass(this.password)
    },
  },

  mounted() {
    document.addEventListener('keydown', this.handleEnter)
  },

  beforeUnmount() {
    document.removeEventListener('keydown', this.handleEnter)
    this.login    = ''
    this.password = ''
  },

  methods: {
    togglePasswordVisibility() {
      if (this.isShowAuthLoader || this.isAuthSuccess) return
      this.showPassword = !this.showPassword
    },

    handleEnter(event) {
      if (event.key === 'Enter' && this.availableConfirmBtn) {
        this.checkAuth()
      }
    },

    validateLogin(value) {
      return typeof value === 'string' && value.trim().length > 0
    },

    validatePass(value) {
      return typeof value === 'string' && value.trim().length > 0
    },

    showDialog(title, text) {
      this.dialogTitle = title
      this.dialogText  = text
      this.dialog      = true
    },

    normalizeRole(role) {
      return String(role || '').trim().toLowerCase()
    },

    async checkAuth() {
      if (this.isShowAuthLoader || this.isAuthSuccess || !this.availableConfirmBtn) return

      this.isShowAuthLoader = true
      this.isAuthSuccess    = false

      try {
        const response = await $.ajax({
          url:         'https://script.google.com/macros/s/AKfycbzZyyerGTUCYlCEdspNAwYkzfELY87SxYGc_ai6slWxF0zrLiFwXWZ2ewAEcoR41E3bmQ/exec',
          type:        'GET',
          crossDomain: true,
          dataType:    'json',
        })

        if (!response || !Array.isArray(response.stuff)) {
          throw new Error('Invalid auth response format')
        }

        const user = response.stuff.find(item => item.LoginName === this.login.trim())

        if (!user) {
          this.showDialog('Сотрудник не найден', 'Убедитесь, что вводите логин правильно')
          return
        }

        if (user.PasswordEmail !== this.password.trim()) {
          this.showDialog('Неправильный пароль', 'Убедитесь, что вводите пароль правильно')
          return
        }

        const authObj = {
          login: user.LoginName,
          role:  this.normalizeRole(user.RoleStatus),
        }

        localStorage.setItem('sale-auth', JSON.stringify(authObj))
        this.isAuthSuccess = true
        this.$emit('updateUserStatus', authObj)

        // Редиректим сразу — не ждём повторной проверки в App.vue
        setTimeout(() => {
          this.$router.replace(ROLE_HOME[authObj.role] || '/')
        }, 800)

      } catch (error) {
        console.error(error)
        this.snackbarText = 'Ошибка загрузки данных с сервера, повторите попытку позже'
        this.snackbar     = true
      } finally {
        if (!this.isAuthSuccess) {
          this.isShowAuthLoader = false
        }
      }
    },
  },
}
</script>

<style lang="scss" scoped>
.login-page {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: transparent;
}

/* ── Обёртка ─────────────────────────────────────────── */
.login-wrap {
  display: grid;
  grid-template-columns: 1fr 1fr;
  width: 860px;
  min-height: unset;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.5);
}

/* ── Левая панель ────────────────────────────────────── */
.left-panel {
  background: linear-gradient(145deg, #1a2744, #0f1f3d);
  padding: 48px 40px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  position: relative;
  overflow: hidden;
}

.left-glow {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;

  &--top {
    width: 300px; height: 300px;
    background: radial-gradient(circle, rgba(249,115,22,.15), transparent 70%);
    top: -80px; right: -80px;
  }

  &--bottom {
    width: 200px; height: 200px;
    background: radial-gradient(circle, rgba(251,191,36,.08), transparent 70%);
    bottom: -40px; left: -40px;
  }
}

/* Бренд */
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  z-index: 1;
}

.brand-logo {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  object-fit: cover;
  filter: drop-shadow(0 0 8px rgba(255,255,255,0.4));
  box-shadow: 0 0 16px rgba(255,255,255,0.15);
}

.brand-name {
  font-size: 16px;
  font-weight: 800;
  color: #fff;
  letter-spacing: 2px;
}

/* Контент */
.left-content { z-index: 1; }

.left-title {
  font-size: 30px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.8px;
  line-height: 1.2;
  margin-bottom: 12px;

  span { color: #f97316; }
}

.left-sub {
  font-size: 13px;
  color: #64748b;
  line-height: 1.6;
}

/* Статистика */
.stats {
  display: flex;
  flex-direction: column;
  gap: 10px;
  z-index: 1;
}

.stat {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: rgba(255, 255, 255, 0.04);
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.stat-dot {
  width: 8px; height: 8px;
  border-radius: 50%; flex-shrink: 0;
}

.stat-text {
  font-size: 12px;
  color: #64748b;

  b { color: #94a3b8; }
}

/* ── Правая панель ───────────────────────────────────── */
.right-panel {
  background: #fff;
  padding: 48px 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 28px;
}

.form-title {
  font-size: 24px;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: -0.5px;
  margin-bottom: 4px;
}

.form-sub {
  font-size: 13px;
  color: #94a3b8;
}

/* ── Поля ────────────────────────────────────────────── */
.fields {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.field-wrap {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 11px;
  font-weight: 700;
  color: #475569;
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.field {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #f8fafc;
  border: 1.5px solid #e2e8f0;
  border-radius: 12px;
  padding: 12px 16px;
  transition: all 0.2s ease;

  &--focus {
    border-color: #f97316;
    background: #fff;
    box-shadow: 0 0 0 3px rgba(249, 115, 22, 0.1);
  }

  &--error {
    border-color: #ef4444;
    background: #fff5f5;
  }
}

.field-icon { flex-shrink: 0; }

.field input {
  border: none;
  background: transparent;
  outline: none;
  font-family: inherit;
  font-size: 14px;
  color: #0f172a;
  font-weight: 500;
  flex: 1;
  min-width: 0;

  &::placeholder { color: #cbd5e1; }
  &:disabled { opacity: 0.6; cursor: not-allowed; }
}

.show-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 2px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  opacity: 0.7;
  transition: opacity 0.15s;

  &:hover { opacity: 1; }
}

/* ── Кнопка ──────────────────────────────────────────── */
.submit-btn {
  width: 100%;
  padding: 14px;
  background: linear-gradient(135deg, #f97316, #fbbf24);
  border: none;
  border-radius: 12px;
  font-family: inherit;
  font-size: 15px;
  font-weight: 700;
  color: #fff;
  cursor: pointer;
  letter-spacing: -0.2px;
  transition: all 0.2s ease;
  box-shadow: 0 4px 16px rgba(249, 115, 22, 0.35);

  &:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 6px 20px rgba(249, 115, 22, 0.45);
  }

  &:active:not(:disabled) { transform: translateY(0); }

  &:disabled { opacity: 0.6; cursor: not-allowed; }

  &--success {
    background: linear-gradient(135deg, #22c55e, #4ade80);
    box-shadow: 0 4px 16px rgba(34, 197, 94, 0.35);
  }
}

.btn-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.btn-spinner {
  width: 18px; height: 18px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

/* ── Футер ───────────────────────────────────────────── */
.form-footer {
  font-size: 11px;
  color: #cbd5e1;
  text-align: center;
}

/* ── Адаптив ─────────────────────────────────────────── */
/* Планшет — прячем левую панель */
@media (max-width: 780px) {
  .login-wrap {
    grid-template-columns: 1fr;
    width: 100%;
    max-width: 420px;
    min-height: unset;
    border-radius: 20px;
  }

  .left-panel { display: none; }

  .right-panel { padding: 36px 28px; }
}

/* Маленький телефон */
@media (max-width: 440px) {
  .login-page { padding: 12px; }

  .login-wrap {
    max-width: 100%;
    border-radius: 16px;
  }

  .right-panel { padding: 28px 20px; gap: 20px; }

  .form-title { font-size: 20px; }

  .submit-btn { font-size: 14px; padding: 12px; }
}
</style>
